def get_bank_databases_sql_catalog() -> List[BankDatabasesSqlRecord]:
    """Return complete bank_databases_sql registry."""
    return REGISTRY_BANK_DATABASES_SQL


def query_bank_databases_sql_by_difficulty(difficulty_level: str) -> List[BankDatabasesSqlRecord]:
    """Filter bank_databases_sql elements matching difficulty."""
    return [item for item in REGISTRY_BANK_DATABASES_SQL if item.difficulty == difficulty_level]


def calculate_bank_databases_sql_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_BANK_DATABASES_SQL)

